#include "nx_physics.h"
#include <cstdio>
#include <cstdlib>
using namespace nx;using namespace nx::game;
#define CHECK(c) do{if(!(c)){std::fprintf(stderr,"FAIL line %d: %s\n",__LINE__,#c);std::exit(1);}}while(false)
void near(float a,float b,float tolerance=.001f){if(std::abs(a-b)>tolerance){std::fprintf(stderr,"values %.9g %.9g\n",a,b);CHECK(false);}}
struct Fixture {PhysicsPack physics;GraphPack graph;ActorPack actors;JointPack joints;};
Fixture fixture(uint32_t kind=CharacterJoint,bool projection=false){
 Fixture f;auto&p=f.physics.player;p.objectId=1;p.position={100,100,0};p.up={0,1,0};p.forward={0,0,1};p.walkSpeed=750;p.airAcceleration=6000;p.jumpPower=90;p.wallJumpPower=150;p.mass=100;p.radius=.5f;p.height=3.5f;p.gravity={0,-40,0};f.physics.layerMasks.fill(~0u);
 ColliderRecord c{};c.id=500;c.objectId=3;c.bodyId=300;c.kind=Sphere;c.flags=Active|Enabled|AttachedBody;c.world[0]=c.world[5]=c.world[10]=1;c.radius=.1f;f.physics.colliders.push_back(c);
 auto&g=f.graph;std::string types="TransformRigidbody";const char*jointName=kind==CharacterJoint?"CharacterJoint":kind==FixedJoint?"FixedJoint":"ConfigurableJoint";types+=jointName;g.strings.assign(types.begin(),types.end());
 for(unsigned i=0;i<3;i++){GraphNode n{};n.objectId=i+1;n.transformId=1000+i;n.parent=-1;n.flags=1;n.layer=i?0:2;n.firstComponent=g.components.size();n.componentCount=i==2?3:2;n.position=i==0?p.position:i==1?Vec3{0,2,0}:Vec3{};n.scale={1,1,1};n.rotation[3]=1;g.nodes.push_back(n);g.components.push_back({n.transformId,i,0,9,0,0,1});g.components.push_back({int64_t(100+i*100),i,9,9,0,0,1});if(i==2)g.components.push_back({400,i,18,uint32_t(std::strlen(jointName)),0,0,1});}
 auto&a=f.actors;std::memcpy(a.header.magic,"NXACTOR\0",8);a.header.version=1;a.header.bodyCount=3;a.header.colliderCount=1;a.header.graphCrc=g.checksum();a.header.physicsCrc=physicsChecksum(f.physics);
 for(unsigned i=0;i<3;i++){ActorRecord b{};b.id=100+i*100;b.objectId=i+1;b.flags=ActorActive|ActorImplicitCenter|ActorImplicitTensor|(i==0?ActorPlayer:0u)|(i==1?ActorKinematic:0u)|(i==2?ActorHasJoint:0u);b.layer=i?0:2;b.position=g.nodes[i].position;b.rotation[3]=b.inertiaRotation[3]=1;b.mass=i?1:100;b.inertia={1,1,1};b.colliderCount=i==2?1:0;a.bodies.push_back(b);}a.colliders={{0,1}};
 auto&j=f.joints;std::memcpy(j.header.magic,"NXJOINT\0",8);j.header.version=1;j.header.count=1;j.header.actorCrc=actorChecksum(a);j.header.graphCrc=g.checksum();JointRecord r{};r.id=400;r.body=300;r.connected=200;r.objectId=3;r.kind=kind;r.flags=JointEnabled|JointAutoAnchor;r.axis={0,1,0};r.anchor={0,2,0};r.twistLow=-20;r.twistHigh=70;r.swing1=30;r.projection=projection;r.projectionDistance=.1f;r.projectionAngle=180;r.breakForce=r.breakTorque=INFINITY;r.massScale=r.connectedMassScale=1;r.targetRotation[3]=1;for(unsigned i=0;i<6;i++)r.motion[i]=i<3?0:1;if(kind!=CharacterJoint){r.secondary={1,0,0};if(kind==ConfigurableJoint)for(unsigned i=3;i<6;i++)r.motion[i]=2;}j.joints.push_back(r);return f;
}
void initialize(PhysicsWorld&world,const Fixture&f){WorldGraph graph;std::string error;CHECK(graph.initialize(f.graph,error));CHECK(world.initialize(f.physics,0,error));if(!world.initializeJoints(f.joints,f.actors,f.graph,error)){std::fprintf(stderr,"joint init: %s\n",error.c_str());CHECK(false);}CHECK(world.initializeActors(f.actors,f.graph,graph,error));}
void step(PhysicsWorld&w,unsigned count){std::string error;for(unsigned i=0;i<count;i++)if(!w.step(.008f,error)){std::fprintf(stderr,"step: %s\n",error.c_str());CHECK(false);}}
void fixtures(){
 for(float spin:{-10.f,10.f}){
  auto f=fixture();PhysicsWorld world;initialize(world,f);std::string error;ActorPose pose;CHECK(world.actorPose(300,pose,error));pose.angularVelocity={0,spin,0};CHECK(world.setActorPose(300,pose,error));step(world,125);CHECK(world.actorPose(300,pose,error));float angle=2*std::atan2(pose.rotation[1],pose.rotation[3])*180/3.14159265359f;near(angle,spin>0?20:-70,.05f);NativeJointState state;CHECK(world.jointState(400,state,error)&&state.attached&&!state.broken);CHECK(state.anchorError<.002f);CHECK(world.coverage().activeJoints==1);
  CHECK(world.setJointEnabled(400,false,error));CHECK(world.coverage().activeJoints==0);CHECK(world.setJointEnabled(400,true,error));step(world,1);CHECK(world.coverage().activeJoints==1);CHECK(world.setActorActive(200,false,error));CHECK(world.coverage().activeJoints==0);step(world,1);CHECK(world.setActorActive(200,true,error));step(world,1);CHECK(world.coverage().activeJoints==1);
  CHECK(world.setActorActive(300,false,error));CHECK(world.actorPose(300,pose,error));pose.rotation[0]=pose.rotation[2]=0;pose.rotation[1]=pose.rotation[3]=std::sqrt(.5f);pose.angularVelocity={};pose.velocity={};CHECK(world.setActorPose(300,pose,error));CHECK(world.setActorActive(300,true,error));step(world,250);CHECK(world.actorPose(300,pose,error));near(2*std::atan2(pose.rotation[1],pose.rotation[3])*180/3.14159265359f,20,.05f);
 }
 for(uint32_t kind:{uint32_t(FixedJoint),uint32_t(ConfigurableJoint)}){
  auto f=fixture(kind);PhysicsWorld world;initialize(world,f);std::string error;ActorPose pose;CHECK(world.actorPose(300,pose,error));pose.angularVelocity={0,10,0};pose.velocity={1,0,0};CHECK(world.setActorPose(300,pose,error));step(world,125);NativeJointState state;CHECK(world.jointState(400,state,error));CHECK(state.attached&&state.anchorError<.01f);CHECK(world.actorPose(300,pose,error));if(kind==FixedJoint)near(pose.rotation[1],0,.005f);else CHECK(std::abs(pose.rotation[1])>.1f);
 }
 auto f=fixture(FixedJoint,true);f.joints.joints[0].projectionDistance=.001f;PhysicsWorld projected;initialize(projected,f);std::string error;ActorPose pose;CHECK(projected.actorPose(300,pose,error));pose.position.x=10;CHECK(projected.setActorPose(300,pose,error));step(projected,1);NativeJointState state;CHECK(projected.jointState(400,state,error));CHECK(state.anchorError<.002f);
 f=fixture(FixedJoint);f.joints.joints[0].breakForce=0;PhysicsWorld breaking;initialize(breaking,f);CHECK(breaking.actorPose(300,pose,error));pose.position.x=10;pose.velocity.x=100;CHECK(breaking.setActorPose(300,pose,error));step(breaking,1);CHECK(breaking.jointState(400,state,error));CHECK(state.broken&&!state.attached&&breaking.jointBreakEvents().size()==1);CHECK(!breaking.setJointEnabled(400,true,error));breaking.clearJointBreakEvents();CHECK(breaking.jointBreakEvents().empty());
 f=fixture();PhysicsWorld modes;initialize(modes,f);CHECK(modes.setActorKinematic(300,true,error));CHECK(modes.actorKinematic(300));step(modes,1);CHECK(modes.setActorKinematic(300,false,error));CHECK(!modes.actorKinematic(300));step(modes,1);CHECK(modes.coverage().activeJoints==1);
 std::puts("PASS: native Character/Fixed/Configurable constraints, Unity twist-sign boundaries (+20/-70 degrees), persistent frames, actor/joint lifecycle, mode changes, anchor projection and break event ownership");
}
void shapeAndFrozen(){
 std::string error;
 for(float scale:{0.f,1e-8f,.001f}){
  auto f=fixture();auto&c=f.physics.colliders[0];c.kind=Box;c.radius=0;c.size[0]=2;c.size[1]=1.5f;c.size[2]=1;c.center[0]=-.62f;c.center[2]=-.12f;c.world[0]=c.world[5]=c.world[10]=scale;f.graph.nodes[2].scale={scale,scale,scale};f.actors.header.physicsCrc=physicsChecksum(f.physics);f.actors.header.graphCrc=f.graph.checksum();f.joints.header.actorCrc=actorChecksum(f.actors);f.joints.header.graphCrc=f.graph.checksum();PhysicsWorld world;initialize(world,f);
  auto hit=world.ray({1,0,0},{-2,0,0},~0u);CHECK(hit.hit&&hit.collider==500);near(hit.point.x,-.62f*scale+std::max(1.1920928955078125e-7f,scale),4e-8f);std::vector<int64_t> overlaps;CHECK(world.overlapCapsule({},{},1e-7f,~0u,false,overlaps,error));if(overlaps.size()!=1)std::fprintf(stderr,"scale %.9g overlap count %zu\n",scale,overlaps.size());CHECK(overlaps.size()==1&&overlaps[0]==500);
 }
 auto f=fixture();f.graph.components.pop_back();f.graph.nodes[2].componentCount--;f.actors.bodies[2].flags=(f.actors.bodies[2].flags&~uint32_t(ActorHasJoint))|ActorGravity;f.actors.bodies[2].constraints=126;f.actors.header.graphCrc=f.graph.checksum();f.joints.joints.clear();f.joints.header.count=0;f.joints.header.actorCrc=actorChecksum(f.actors);f.joints.header.graphCrc=f.graph.checksum();PhysicsWorld world;initialize(world,f);ActorPose pose;CHECK(world.actorPose(300,pose,error));auto origin=pose.position;pose.velocity={10,-20,30};pose.angularVelocity={1,2,3};CHECK(world.setActorPose(300,pose,error));CHECK(world.actorPose(300,pose,error));near(dot(pose.velocity,pose.velocity),0);near(dot(pose.angularVelocity,pose.angularVelocity),0);CHECK(!world.actorKinematic(300));step(world,125);CHECK(world.actorPose(300,pose,error));near(dot(pose.position-origin,pose.position-origin),0);CHECK(world.setActorKinematic(300,true,error));CHECK(world.setActorKinematic(300,false,error));step(world,1);CHECK(world.actorPose(300,pose,error));near(dot(pose.position-origin,pose.position-origin),0);
 std::puts("PASS: Unity-referenced zero/tiny box half-extent clamp and query identity; fully frozen logical dynamic bodies reject velocity immediately and retain position across solver/mode updates");
}
void actual(const char*joints,const char*actors,const char*graph){
 JointPack j;ActorPack a;GraphPack g;std::string error;CHECK(j.load(joints,error));CHECK(a.load(actors,error));CHECK(g.load(graph,error));if(!j.bind(a,g,error)){std::fprintf(stderr,"actual bind: %s\n",error.c_str());CHECK(false);}CHECK(j.joints.size()==986);unsigned kinds[4]={},supported=0,zero=0;for(const auto&r:j.joints){kinds[r.kind]++;Vec3 x,y;CHECK(jointAxes(r,x,y,error));near(dot(x,x),1);near(dot(y,y),1);near(dot(x,y),0);zero+=dot(r.secondary,r.secondary)==0;if(jointAdapterSupported(r,error))supported++;}CHECK(kinds[1]==956&&kinds[2]==14&&kinds[3]==16&&zero==119&&supported==986);
 auto bad=j;bad.header.actorCrc^=1;CHECK(!bad.bind(a,g,error));bad=j;bad.joints[0].body=bad.joints[0].connected;CHECK(!bad.validate(error));bad=j;bad.joints[0].axis={};CHECK(!bad.validate(error));
 std::printf("PASS: all %zu authored joint records and bodies bind; %u native configurations supported, including %u zero-secondary cases; complete ragdoll/PhysX parity and console execution remain unverified\n",j.joints.size(),supported,zero);
}
void corruption(const char*path){
 FILE*f=std::fopen(path,"rb");CHECK(f);std::fseek(f,0,SEEK_END);long length=std::ftell(f);std::rewind(f);std::vector<uint8_t> bytes(length);CHECK(std::fread(bytes.data(),1,bytes.size(),f)==bytes.size());std::fclose(f);
 auto reject=[](const std::vector<uint8_t>&data){FILE*f=std::tmpfile();CHECK(f);CHECK(std::fwrite(data.data(),1,data.size(),f)==data.size());std::rewind(f);JointPack pack;std::string error;CHECK(!pack.read(f,error));std::fclose(f);};auto refresh=[](std::vector<uint8_t>&data){reinterpret_cast<JointHeader*>(data.data())->crc=crc32(data.data()+40,data.size()-40);};
 auto bad=bytes;bad.pop_back();reject(bad);bad=bytes;bad.push_back(0);reject(bad);bad=bytes;reinterpret_cast<JointHeader*>(bad.data())->count=UINT32_MAX;reject(bad);for(unsigned i=0;i<12;i++){bad=bytes;bad[40+(i*104729)%(bad.size()-40)]^=1;reject(bad);}bad=bytes;reinterpret_cast<JointRecord*>(bad.data()+40)->axis={};refresh(bad);reject(bad);bad=bytes;reinterpret_cast<JointRecord*>(bad.data()+40)->breakForce=NAN;refresh(bad);reject(bad);bad=bytes;reinterpret_cast<JointRecord*>(bad.data()+40)->motion[5]=3;refresh(bad);reject(bad);
 std::puts("PASS: joint pack exact-length/budget/CRC mutation checks, refreshed-checksum invalid axes/force/motion rejection");
}
int main(int argc,char**argv){fixtures();shapeAndFrozen();if(argc==4){actual(argv[1],argv[2],argv[3]);corruption(argv[1]);}else if(argc!=1)return 2;return 0;}
